1	import type Database from 'better-sqlite3';
2	
3	export interface Migration {
4	  version: number;
5	  description: string;
6	  up(db: Database.Database): void;
7	}
8	
9	export interface MigrationResult {
10	  fromVersion: number;
11	  toVersion: number;
12	  applied: number[];
13	}
14	
15	function assertUniqueVersions(migrations: readonly Migration[]): void {
16	  const seen = new Set<number>();
17	  for (const m of migrations) {
18	    if (seen.has(m.version)) throw new Error(`Duplicate migration version: ${m.version}`);
19	    seen.add(m.version);
20	  }
21	}
22	
23	/** Run pending migrations inside one transaction and record applied versions. */
24	export function runMigrations(db: Database.Database, migrations: readonly Migration[]): MigrationResult {
25	  assertUniqueVersions(migrations);
26	  db.exec(`
27	    CREATE TABLE IF NOT EXISTS _schema_migrations (
28	      version INTEGER PRIMARY KEY,
29	      description TEXT NOT NULL DEFAULT '',
30	      applied_at TEXT NOT NULL DEFAULT (datetime('now'))
31	    )
32	  `);
33	
34	  const row = db.prepare('SELECT COALESCE(MAX(version), 0) AS version FROM _schema_migrations').get() as { version: number };
35	  const fromVersion = Number(row.version ?? 0);
36	  const pending = [...migrations].sort((a, b) => a.version - b.version).filter((m) => m.version > fromVersion);
37	  const applied: number[] = [];
38	
39	  if (pending.length > 0) {
40	    const tx = db.transaction(() => {
41	      const record = db.prepare('INSERT INTO _schema_migrations (version, description) VALUES (?, ?)');
42	      for (const migration of pending) {
43	        migration.up(db);
44	        record.run(migration.version, migration.description);
45	        applied.push(migration.version);
46	      }
47	    });
48	    tx();
49	  }
50	
51	  const toVersion = applied.length > 0 ? applied[applied.length - 1]! : fromVersion;
52	  return { fromVersion, toVersion, applied };
53	}
